mapper.update:
UPDATE task SET updated_at=CURRENT_TIMESTAMP(6)
WHERE tenant_id=#{tenant} AND id=#{task} AND owner_actor_id=#{owner} AND request_digest=#{digest}
  AND state=#{state} AND CURRENT_TIMESTAMP(6)<#{retain}
  AND (#{fresh}=FALSE OR (state='QUEUED' AND current_attempt_id IS NULL AND worker_id IS NULL
    AND cancel_requested_at IS NULL AND deadline>CURRENT_TIMESTAMP(6)))

UPDATE task t JOIN task_attempt a ON a.tenant_id=t.tenant_id AND a.task_id=t.id AND a.id=t.current_attempt_id
SET t.updated_at=CURRENT_TIMESTAMP(6)
WHERE t.tenant_id=#{tenant} AND t.id=#{task} AND t.current_attempt_id=#{attempt}
  AND t.worker_id=#{worker} AND t.fence=#{fence} AND a.worker_id=#{worker} AND a.fence=#{fence}
  AND t.state=#{state} AND a.state=#{attemptState} AND a.ended_at IS NOT NULL
  AND t.lease_until>CURRENT_TIMESTAMP(6) AND t.deadline>CURRENT_TIMESTAMP(6)
  AND t.cancel_requested_at IS NULL AND CURRENT_TIMESTAMP(6)<#{retain}
